inp = input()
target = int(input())

inp = inp.split(",")
nums = [int(i.strip()) for i in inp]

def twoSum(nums, target):
    seen = {}
    for i, num in enumerate(nums):
        if(target - num in seen):
            return [seen[target - num], i]
        else:
            seen[num] = i

print(twoSum(nums, target))
